pairs.translation:
/**
 * Cold reads return `entries`; persistent streams continue after last entries. Replay server opening frames with drafts, empty queued-message snapshots and
 * idle states, then end;
 * retry extends reconnect intervals, avoiding reconnects during tests.
 */

/**
 * Fixture keys: methods plus paths/queries, sorting parameters by name independently of dispatch order/encoding;
 * distinct queries are distinct interfaces, recorded individually. `url` permits complete addresses or /-prefixed paths.
 */

/**
 * jsdom HTMLMediaElement lacks playback: play/pause/load raise "Not implemented".
 * Call before rendering `<video>`/`<audio>` players, replacing methods uniformly with side-effect-free stubs;
 * add newly used methods here only. Return spies for target assertions through `mock.contexts`.
 * Restore through `vi.restoreAllMocks()`.
 */

/**
 * Consumer-progress counters: count each connection and each request for the next stream chunk (`pull`).
 *
 * `pull` is a real handshake: consumers ask again only after reading previous chunks, feeding parsers and returning to `read()`;
 * therefore no new ticks means all written contents have been read and parsed.
 */

/**
   * `decode`: decode errors/unavailable canvas; `oversized`: over budget even at quality floors;
   * `gif`: GIF file signatures.
   */

/**
 * Maximum rejection-summary characters in notifications. Single-line toasts truncate excess with ellipses;
 * never expand full summaries within those toasts.
 */

/**
 * Duration-copy selector, requiring minimal interpolated `common` lookup shapes only;
 * any namespace `t` can pass directly because keys always use `common:` prefixes here.
 */

pairs.source:
/** 返回该 (provider, model) 下的分辨率候选 + 是否自定义供应商（决定 picker 模式）。
 *  自定义供应商路径需要从 endpoint 推 media_type 选标准分辨率集；该 map 由调用方
 *  从 endpoint-catalog-store 读出注入（保持本文件无 store 副作用）。 */

pairs.translation:
/** Return (provider, model) resolution candidates/custom-provider status, determining picker modes.
 *  Custom paths infer media_type from endpoints to select standard resolution sets; callers inject this map
 *  from endpoint-catalog-store, keeping this file free of store side effects. */

/**
 * Server-written texts listing formal-script entries (e.g. overwrite-confirmation loss manifests): replace storyboard/video-unit IDs with
 * positional names such as Storyboard 5, or Deleted when no longer scripted; other entry IDs only lose episode prefixes. Use only when all entries belong to formal scripts;
 * draft-diagnostic IDs denote draft entries and bypass this function.
 */

/**
 * draft→Turn; return null when replaced by authoritative entries.
 * Subagent streaming drafts never enter main timelines, which show collapsed cards only;
 * authoritative entries update card contents near-real-time.
 */

/**
 * Apply deltas purely, returning new objects. Callers first filter by rev thresholds;
 * changed message_id starts new drafts, as identity changes mean previous drafts have authoritative completion.
 */

/**
 * BOM/ZWNBSP mirrors backend `text_parser._BOM`: meaningless in bodies, yet splits byte-based decisions;
 * JS `\s` recognizes it while Python `str.strip()` does not, making frontend tokens fail backend
 * recognition and reversing whether speakers become reference images.
 */

/**
 * Inline whitespace allowed between mentions/`{`. JS `\s` excludes U+001F while Python `str.isspace()` includes it;
 * omitting it makes `@[张三]<U+001F>{我来了}` bind speakers on backends but derive reference images on frontends.
 */

pairs.source:
/* 原语负责限高：Header / Body / Footer 纵向排布，只有 DialogBody 滚动，标题与底部操作始终可见。
          宽度按 size 分档，不让调用处用视口断点覆盖。多步向导（wizard）固定高度，切换步骤时外框与底部按钮不移动。
          图片查看器（viewer）占满视口四周各留 1rem 的区域，大图按可用空间缩放。 */

pairs.translation:
/* Primitives constrain height: vertical Header / Body / Footer layout; only DialogBody scrolls, keeping titles/footer actions visible.
          Width follows size tiers; callers must not override with viewport breakpoints. Wizards have fixed heights so frames/footer buttons stay still across steps.
          Viewers fill viewports with 1rem margins on each side, scaling large images to available space. */

/**
 * Project ZIP exports shared by workspace headers/lobby card menus. Scope selection starts browser downloads, silently on successful start;
 * exports carrying diagnostics show counts/list diagnostics; failures show causes and enter workspace notifications.
 */

/**
 * Workspace sidebars: overview/episodes/character/scene/prop navigation above, ads adding products without episodes;
 * episode search/order/actions below. Shell resize handles set widths, collapsed as icon rails.
 */

pairs.source:
/**
 * 侧栏的集卡片：左边是播出位置，中间是集名、状态与进度，右边是实际费用。当前打开的集带底色。
 */

pairs.translation:
/**
 * Sidebar episode cards: broadcast positions left, names/status/progress middle, actual costs right; current episodes have backgrounds.
 */

/**
 * Header status-bar Next step presentation: projected from project production state `next_action` and `next_alternatives`;
 * the UI never infers next steps itself.
 *
 * Three button kinds: `nav` navigates to workbench locations that can complete steps; `agent` prefills requests for users to confirm sending;
 * `ai` submits directly (currently only AI episode planning). Actions without direct Web entry points offer only `agent`.
 */

/**
 * Storyboard labels for running tasks. Persisted completed records derive `segment_id` through backend `segment_id_for`;
 * running rows use identical allowlists here, preventing character/prop/scene image tasks from showing
 * Storyboard <name> while running and generic targets after completion.
 */

/**
 * Project running tasks into rows. Tasks lack models/call rows, leaving models empty for Pending resolution;
 * timing starts at `started_at`, or `queued_at` before starting. Local rendering tasks (`render`) call no
 * providers, record no usage and have no rows; return null.
 */

/**
 * Usage-page project names: show titles when available, otherwise names (deleted/unreadable/untitled projects);
 * deleted projects show original names/deletion dates; projectless endpoint trials show Untitled.
 */

/**
 * Targets: storyboards/video units begin with untruncated positional badges/thumbnails; following episode titles/body excerpts truncate when needed;
 * grids/other such entries begin with episode-local IDs; remaining records show uses only.
 */

/**
 * Count ticks: first integer step in 1 / 2 / 5 × 10ⁿ placing maxima within 4 segments;
 * fractional calls are meaningless, so ticks never use decimals.
 */

/**
 * Agent-provider lists (Agent credentials in data). Add/edit, delete and activation changes execute immediately: successful changes update lists;
 * failures show notifications. Irreversible deletions first require AlertDialog confirmation.
 */

/**
 * Actual models/pricing states for Agent-provider tiers. Each row has tier, model name, matching model entry or Unpriced, then tier actions;
 * rows are subgrids of outer grids. Unpriced tiers offer Select model; manually selected tiers (including removed models) offer Unbind.
 */

pairs.source:
/** 默认层下拉的执行路径。默认层跨全部用途，路径只能由调用方的上下文给出（项目是否走参考生
   *  视频）；全局设置页无项目上下文，省略即回退目录 i2v 位。细分项下拉不看此值——它们各自的
   *  `key` 就是路径，见下方 `asVideoRoute`。 */

pairs.translation:
/** Default-layer dropdown execution paths. Default layers span all uses; only caller contexts provide paths (whether projects use reference-to-
   *  video). Global settings lack project contexts; omission falls back to catalog i2v positions. Subdivision dropdowns ignore this value: their
   *  `key` is already the path; see `asVideoRoute` below. */

/**
   * Whether projects use reference-to-video (direct asset-image output). Some models restrict reference-path durations to single values;
   * filter duration options accordingly. Owning pages know modes, supplying them externally instead of inference here.
   */

/**
 * Render built-in provider brand icons by canonical IDs when ICON_REGISTRY matches;
 * otherwise use letter badges, valid final states for providers absent from icon libraries.
 */

/**
   * Pass false inside focusable elements such as buttons: truncated text no longer enters Tab order independently (nested focusables violate WCAG 4.1.2);
   * hover still reveals full text, and screen readers read it from outer accessible names.
   */

/**
 * Sortable lists: mouse/touch handle dragging, or focus handles then Space to pick up, arrows to move, Space to drop, Esc to cancel;
 * announce pickup/movement/drop/cancellation. Supply behavior only without containers; callers write list elements,
 * using `SortableItem` entries/`SortableHandle` handles. Non-drag movement (Move up/down menus)
 * uses `useSortableMove`.
 */

/**
 * Leave-guard registries and sole interception dialogs, mounted at route roots (empty `base`).
 * Intercept in-app navigation through wouter `aroundNav`; browser Forward/Back first returns to original URLs, then asks;
 * tab closing/refreshing uses native browser `beforeunload` prompts.
 */

/**
   * Execute permitted actions and discard units in `discardIds`. Discard immediately after synchronous completion;
   * async actions discard only after successful settlement, notifying units to stop requiring external-removal retention while pending and restoring on failure.
   */

/**
 * One-sentence causes localized by problem codes with `params`. Unknown codes use generic causes for returned actions;
 * unknown actions use broadest explanations. Summaries expose no raw text/problem codes/reason codes; raw text goes in collapsed details.
 */

/**
 * Inline-expanded next steps: explanations, extra instructions, primary/secondary entries and Or alternatives. Accent fills cover only these blocks;
 * all secondary text uses subtle because muted atop popover/accent fills falls below 4.5:1.
 */

/**
 * Resolve URL parameters into selections: `file=new` selects new-file forms; nonexistent files (deleted, cleared or mistyped) fall back to first entries;
 * empty lists show new-file forms. Delete/clear leave URLs unchanged; selections settle during rendering.
 */

/**
 * Prefetch settings while onboarding runs: crossing from lobbies requires anchors within bounded waits;
 * fetching chunks only at navigation would consume those waits.
 */

pairs.source:
/* 演示项目没有可用的项目级设置（后端不存在该项目）——地址栏直达、书签或外部链接
              都可能绕开 GlobalHeader 里已做的重定向，这里在路由层再挡一次，指向全局设置。
              必须排在下面通用的项目设置路由之前，wouter 按声明顺序匹配。 */

pairs.translation:
/* Demo projects lack usable project settings because backends have none; direct URLs/bookmarks/external links
              bypass GlobalHeader redirects, so guard routes again, pointing to globals.
              Place before general project-setting routes, since wouter matches declaration order. */

/**
 * Generic request errors: `message` contains backend product-language summaries, directly displayable;
 * optional `diagnostic` carries context-specific diagnostic/remediation data, never appended to `message`.
 */

/**
 * Whether read-only gates should block requests. Allow writes targeting specific real projects:
 * demo mode may have started just before requests were sent, but cannot block operations already initiated from real projects;
 * continue blocking requests targeting demos or lacking project ownership (global asset libraries, etc.),
 * except narrowly exempted system endpoints.
 */

pairs.source:
/**
 * 通用请求：拼接 API 前缀、注入凭证并过只读闸门，非 2xx 时按错误契约抛出对应错误。
 */

pairs.translation:
/**
 * Generic requests: prepend API prefixes, inject credentials and apply read-only gates; throw corresponding contract errors for non-2xx responses.
 */

/**
   * Destination prefixes including subroutes after `interactive` anchor clicks, caller-defined and
   * uninterpreted here. Passed unchanged to distinguish following intended entries from unrelated navigation;
   * former advances naturally, latter forces return. Meaningful only for true `interactive`.
   */

/**
 * After structural/text changes, invoke once next frame. Drivers realign highlights only on resize/scroll;
 * newly rendered preceding content (lobby greetings appearing after Example projects when returning from settings)
 * pushes anchors without highlights following. Ignore attribute changes: driver alignment writes attributes only.
 */

/**
   * Previous shared by buttons/`ArrowLeft`, preserving reporting. First steps have no predecessors;
   * driver disables buttons but keyboard paths lack that disabled state. Without guards,
   * `instance.movePrevious()` destroys entire tours when driver.js finds no preceding steps.
   */

/**
 * Targets within Providers sections and corresponding URL parameters:
 * - `{ preset, model? }` → `provider=<预置供应商 id>`;
 * - `{ custom, model? }` → `custom=<自定义供应商 id>`;
 *   either opens model Sheets when carrying `model=<模型 ID>`;
 * - `{ newCustom }` → `custom=new`, optionally `endpoint=<端点 key>` and `base_url=<接口地址>` to prefill new-provider forms
 *   (the endpoint Create provider and use action).
 */

/**
 * Route-segment constants beneath `/app/projects/:projectName`: `router.tsx` (project settings) and
 * `StudioCanvasRouter` (inner `<Switch>`) both source `<Route path>` values here;
 * `APP_PROJECT_WORKSPACE_PATTERN` also combines them, so adding/renaming routes changes only this location.
 */
